1	package consensus
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"sync"
13	)
14	
15	// Config 是节点初始化时固定的配置。
16	type Config struct {
17		// Seed 决定每轮提议者的种子，任意非空字节。
18		Seed []byte
19		// Validators 固定、非空、无重复的验证者公钥名单（Ed25519 32 字节公钥）。
20		Validators [][]byte
21		// MaxTxsPerBlock 单块交易上限，必须为正整数。
22		MaxTxsPerBlock uint64
23	}
24	
25	// entryStatus 与对外的 TxStatus 取值一致，额外区分内部存储。
26	type entryStatus string
27	
28	const (
29		stQueued    entryStatus = "queued"
30		stProposed  entryStatus = "proposed"
31		stConfirmed entryStatus = "confirmed"
32		stReplaced  entryStatus = "replaced"
33		stExpired   entryStatus = "expired"
34	)
35	
36	type poolEntry struct {
37		Tx         *Transaction `json:"tx"`
38		Status     entryStatus  `json:"status"`
39		ReplacedBy string       `json:"replaced_by,omitempty"`
40	}
41	
42	type confirmedRef struct {
43		Height uint64 `json:"height"`
44		Block  string `json:"block_id"`
45	}
46	
47	type proposalState struct {
48		Round   uint64   `json:"round"`
49		TxIDs   []string `json:"tx_ids"`
50		BlockID string   `json:"block_id"`
51		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
52	}
53	
54	// state 是持久化到磁盘的完整节点状态。
55	type state struct {
56		Version    int                          `json:"version"`
57		Seed       []byte                       `json:"seed"`
58		Validators [][]byte                     `json:"validators"`
59		MaxTxs     uint64                       `json:"max_txs_per_block"`
60		Round      uint64                       `json:"round"`
61		LastBlock  string                       `json:"last_block_id"`
62		Accounts   map[string]uint64            `json:"accounts"` // 发送者十六进制公钥 -> 已确认序号
63		Pool       map[string]map[uint64]string `json:"pool"`     // 发送者 -> 序号 -> 交易标识（含已提议交易）
64		Entries    map[string]*poolEntry        `json:"entries"`
65		Confirmed  map[string]confirmedRef      `json:"confirmed"`
66		Blocks     []Block                      `json:"blocks"`
67		Proposal   *proposalState               `json:"proposal,omitempty"`
68	}
69	
70	const stateVersion = 1
71	const stateFileName = "state.json"
72	
73	// Node 是一个本地共识节点。一个进程内可串行调用其方法。
74	type Node struct {
75		dir string
76		mu  sync.Mutex
77		st  *state
78		// injectSaveErr 仅供同包测试使用：非 nil 时 save 直接失败，模拟写入错误。
79		injectSaveErr error
80	}
81	
82	func validateConfig(cfg Config) error {
83		if len(cfg.Seed) == 0 {
84			return errors.New("seed must be non-empty")
85		}
86		if len(cfg.Validators) == 0 {
87			return errors.New("validators must be non-empty")
88		}
89		if cfg.MaxTxsPerBlock == 0 {
90			return errors.New("max txs per block must be a positive integer")
91		}
92		seen := make(map[string]struct{}, len(cfg.Validators))
93		for i, v := range cfg.Validators {
94			if len(v) == 0 {
95				return fmt.Errorf("validator %d is empty", i)
96			}
97			key := fmt.Sprintf("%x", v)
98			if _, ok := seen[key]; ok {
99				return fmt.Errorf("duplicate validator %s", key)
100			}
101			seen[key] = struct{}{}
102		}
103		return nil
104	}
105	
106	// New 在 dir 中初始化一个新节点。目录不存在会创建；若已有状态文件则报错，
107	// 以免覆盖既有链历史，请改用 Open。
108	func New(dir string, cfg Config) (*Node, error) {
109		if err := validateConfig(cfg); err != nil {
110			return nil, err
111		}
112		if err := os.MkdirAll(dir, 0o755); err != nil {
113			return nil, err
114		}
115		path := filepath.Join(dir, stateFileName)
116		if _, err := os.Stat(path); err == nil {
117			return nil, fmt.Errorf("state file already exists at %s; use Open to resume", path)
118		}
119		validators := make([][]byte, len(cfg.Validators))
120		for i, v := range cfg.Validators {
121			validators[i] = append([]byte(nil), v...)
122		}
123		st := &state{
124			Version:    stateVersion,
125			Seed:       append([]byte(nil), cfg.Seed...),
126			Validators: validators,
127			MaxTxs:     cfg.MaxTxsPerBlock,
128			Round:      1, // 轮次从 1 开始
129			Accounts:   map[string]uint64{},
130			Pool:       map[string]map[uint64]string{},
131			Entries:    map[string]*poolEntry{},
132			Confirmed:  map[string]confirmedRef{},
133			Blocks:     []Block{},
134		}
135		n := &Node{dir: dir, st: st}
136		if err := n.save(st); err != nil {
137			return nil, err
138		}
139		return n, nil
140	}
141	
142	// Open 从 dir 恢复此前由 New 创建的节点，恢复轮次、交易池、未决提议、票数与确认历史。
143	func Open(dir string) (*Node, error) {
144		path := filepath.Join(dir, stateFileName)
145		raw, err := os.ReadFile(path)
146		if err != nil {
147			return nil, err
148		}
149		st := &state{}
150		if err := json.Unmarshal(raw, st); err != nil {
151			return nil, fmt.Errorf("corrupt state file %s: %w", path, err)
152		}
153		if st.Version != stateVersion {
154			return nil, fmt.Errorf("unsupported state version %d", st.Version)
155		}
156		if st.Round == 0 {
157			st.Round = 1
158		}
159		return &Node{dir: dir, st: st}, nil
160	}
161	
162	// ConfigSnapshot 返回节点的固定配置副本。
163	type ConfigSnapshot struct {
164		Seed           []byte
165		Validators     [][]byte
166		MaxTxsPerBlock uint64
167	}
168	
169	// Config 返回初始化时的配置副本。
170	func (n *Node) Config() ConfigSnapshot {
171		n.mu.Lock()
172		defer n.mu.Unlock()
173		vals := make([][]byte, len(n.st.Validators))
174		for i, v := range n.st.Validators {
175			vals[i] = append([]byte(nil), v...)
176		}
177		return ConfigSnapshot{
178			Seed:           append([]byte(nil), n.st.Seed...),
179			Validators:     vals,
180			MaxTxsPerBlock: n.st.MaxTxs,
181		}
182	}
183	
184	// CurrentRound 返回当前轮次，首轮为 1。
185	func (n *Node) CurrentRound() uint64 {
186		n.mu.Lock()
187		defer n.mu.Unlock()
188		return n.st.Round
189	}
190	
191	// proposerAt 是确定性的轮次提议者选择：
192	// 对 seed || round(大端 8 字节) 取 SHA-256，结果对名单人数取模。
193	// 种子、名单顺序与轮次相同时，提议者必然相同。
194	func proposerAt(seed []byte, validators [][]byte, round uint64) []byte {
195		var buf [8]byte
196		binary.BigEndian.PutUint64(buf[:], round)
197		h := sha256.New()
198		h.Write(seed)
199		h.Write(buf[:])
200		sum := h.Sum(nil)
201		idx := binary.BigEndian.Uint64(sum[:8]) % uint64(len(validators))
202		return validators[idx]
203	}
204	
205	// ProposerFor 返回指定轮次的提议者公钥。
206	func (n *Node) ProposerFor(round uint64) []byte {
207		n.mu.Lock()
208		defer n.mu.Unlock()
209		return append([]byte(nil), proposerAt(n.st.Seed, n.st.Validators, round)...)
210	}
211	
212	// CurrentProposer 返回当前轮次的提议者公钥。
213	func (n *Node) CurrentProposer() []byte {
214		return n.ProposerFor(n.CurrentRound())
215	}
216	
217	// SubmitResult 是交易提交结果。
218	type SubmitResult struct {
219		// TxID 被接受交易的标识。
220		TxID string
221		// ReplacedID 若本次提交替换了旧交易，为旧交易标识；否则为空。
222		ReplacedID string
223	}
224	
225	// Submit 校验并接收一笔交易进入交易池。
226	// 拒绝时返回 *RejectError，可通过其 Reason 取得具体原因。
227	func (n *Node) Submit(tx *Transaction) (*SubmitResult, error) {
228		if tx == nil {
229			return nil, errors.New("nil transaction")
230		}
231		n.mu.Lock()
232		defer n.mu.Unlock()
233	
234		cur := n.st
235		if tx.Sequence == 0 {
236			return nil, reject("sequence-must-be-positive", "sequence must be a positive integer")
237		}
238		if !tx.Verify() {
239			return nil, reject(ReasonBadSignature, "signature verification failed for sender %x", tx.Sender)
240		}
241		id := tx.ID()
242		// 同一标识的交易再次提交，一律视为重复（即使此前已确认、被替换或过期）。
243		if _, ok := cur.Entries[id]; ok {
244			return nil, reject(ReasonDuplicate, "transaction %s already exists", id)
245		}
246		if cur.Round >= tx.Expiry {
247			return nil, reject(ReasonExpired, "expiry round %d is not greater than current round %d", tx.Expiry, cur.Round)
248		}
249		sender := tx.SenderHex()
250		if confirmed := cur.Accounts[sender]; tx.Sequence <= confirmed {
251			return nil, reject(ReasonOldSequence, "sequence %d is not greater than confirmed sequence %d", tx.Sequence, confirmed)
252		}
253		seqs := cur.Pool[sender]
254		if seqs != nil {
255			if oldID, ok := seqs[tx.Sequence]; ok {
256				old := cur.Entries[oldID]
257				if old.Status == stProposed {
258					return nil, reject(ReasonProposalLocked, "sequence %d is already in the current proposal and cannot be replaced", tx.Sequence)
259				}
260				if tx.Fee <= old.Tx.Fee {
261					return nil, reject(ReasonLowFee, "new fee %d is not strictly higher than existing fee %d", tx.Fee, old.Tx.Fee)
262				}
263			}
264		}
265	
266		// 校验通过后在副本上修改，落盘成功才替换内存，失败时确认前状态保持不变。
267		st := cur.clone()
268		result := &SubmitResult{TxID: id}
269		if oldID, ok := st.Pool[sender][tx.Sequence]; ok {
270			old := st.Entries[oldID]
271			old.Status = stReplaced
272			old.ReplacedBy = id
273			result.ReplacedID = oldID
274		}
275	
276		txCopy := *tx
277		txCopy.Sender = append([]byte(nil), tx.Sender...)
278		txCopy.Content = append([]byte(nil), tx.Content...)
279		txCopy.Signature = append([]byte(nil), tx.Signature...)
280		st.Entries[id] = &poolEntry{Tx: &txCopy, Status: stQueued}
281		if st.Pool[sender] == nil {
282			st.Pool[sender] = map[uint64]string{}
283		}
284		st.Pool[sender][tx.Sequence] = id
285	
286		if err := n.save(st); err != nil {
287			return nil, err
288		}
289		n.st = st
290		return result, nil
291	}
292	
293	// 额外拒绝原因。
294	const (
295		// ReasonProposalLocked 同发送者同序号交易已在当前提议中，禁止替换。
296		ReasonProposalLocked = "tx-in-proposal"
297		// ReasonUnknownTx 查询的交易标识不存在。
298		ReasonUnknownTx = "unknown-transaction"
299		// ReasonUnknownBlock 查询的区块高度不存在。
300		ReasonUnknownBlock = "unknown-block"
301	)
302	
303	// ProposalView 是当前轮次提议的只读视图。
304	type ProposalView struct {
305		Round   uint64
306		BlockID string
307		TxIDs   []string
308		// Empty 表示本轮是否为空块提议（无交易）。
309		Empty bool
310	}
311	
312	// Proposal 返回当前轮次提议；尚未提议时第二个返回值为 false。
313	// 重复调用返回同一内容。
314	func (n *Node) Proposal() (ProposalView, bool) {
315		n.mu.Lock()
316		defer n.mu.Unlock()
317		if n.st.Proposal == nil {
318			return ProposalView{}, false
319		}
320		ids := append([]string(nil), n.st.Proposal.TxIDs...)
321		return ProposalView{
322			Round:   n.st.Proposal.Round,
323			BlockID: n.st.Proposal.BlockID,
324			TxIDs:   ids,
325			Empty:   len(ids) == 0,
326		}, true
327	}
328	
329	// Propose 返回当前轮次唯一的提议；重复请求返回同一提议。
330	// 提议生成后即冻结：此后新提交的交易不改变该提议，提议中的交易禁止替换。
331	func (n *Node) Propose() (ProposalView, error) {
332		n.mu.Lock()
333		defer n.mu.Unlock()
334		if n.st.Proposal != nil {
335			return n.proposalView(n.st.Proposal), nil
336		}
337	
338		st := n.st.clone()
339		txIDs := st.selectTransactions()
340		height := uint64(len(st.Blocks)) + 1
341		blockID := BlockID(st.Round, height, st.LastBlock, txIDs)
342		p := &proposalState{
343			Round:   st.Round,
344			TxIDs:   txIDs,
345			BlockID: blockID,
346			Votes:   []string{},
347		}
348		st.Proposal = p
349		for _, id := range txIDs {
350			st.Entries[id].Status = stProposed
351		}
352		if err := n.save(st); err != nil {
353			return ProposalView{}, err
354		}
355		n.st = st
356		return n.proposalView(p), nil
357	}
358	
359	func (n *Node) proposalView(p *proposalState) ProposalView {
360		ids := append([]string(nil), p.TxIDs...)
361		return ProposalView{Round: p.Round, BlockID: p.BlockID, TxIDs: ids, Empty: len(ids) == 0}
362	}
363	
364	// selectTransactions 执行确定性打包：
365	// 每轮从各账户“下一条可确认”的交易中选费用最高者，费用相同按交易标识字典序；
366	// 选入某账户后才继续考虑其后续序号，直到达到上限或没有可选交易。
367	func (n *state) selectTransactions() []string {
368		var picked []string
369		// 每个账户在本次打包中下一个可考虑的序号。
370		next := map[string]uint64{}
371		for sender := range n.Pool {
372			next[sender] = n.Accounts[sender] + 1
373		}
374		for uint64(len(picked)) < n.MaxTxs {
375			var bestID string
376			var bestFee uint64
377			var bestSet bool
378			// 遍历发送者名单需确定序：按发送者十六进制定序，保证选择只取决于费用与标识。
379			senders := make([]string, 0, len(n.Pool))
380			for s := range n.Pool {
381				senders = append(senders, s)
382			}
383			sort.Strings(senders)
384			for _, sender := range senders {
385				id, ok := n.Pool[sender][next[sender]]
386				if !ok {
387					continue
388				}
389				e := n.Entries[id]
390				if e.Status != stQueued {
391					continue
392				}
393				if !bestSet || e.Tx.Fee > bestFee || (e.Tx.Fee == bestFee && id < bestID) {
394					bestID = id
395					bestFee = e.Tx.Fee
396					bestSet = true
397				}
398			}
399			if !bestSet {
400				break
401			}
402			picked = append(picked, bestID)
403			next[n.Entries[bestID].Tx.SenderHex()]++
404		}
405		if picked == nil {
406			picked = []string{}
407		}
408		return picked
409	}
410	
411	// VoteResult 是投票处理结果。
412	type VoteResult struct {
413		// Counted 本次投票是否新计入票数（重复投同一票为 false）。
414		Counted bool
415		// Confirmed 本次投票是否令区块立即确认。
416		Confirmed bool
417		// Block 确认时为新区块；否则为 nil。
418		Block *Block
419	}
420	
421	// Vote 处理验证者投票。票数严格超过名单人数三分之二时立即确认。
422	// 名单外身份、错误轮次、错误区块标识返回带具体 Reason 的 *RejectError；
423	// 重复投同一票不增加票数但不报错。
424	func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
425		n.mu.Lock()
426		defer n.mu.Unlock()
427	
428		key := fmt.Sprintf("%x", validator)
429		allowed := false
430		for _, v := range n.st.Validators {
431			if fmt.Sprintf("%x", v) == key {
432				allowed = true
433				break
434			}
435		}
436		if !allowed {
437			return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
438		}
439		// 轮次优先判定：旧轮次投票不能影响新提议，即使新轮次尚未产生提议。
440		if n.st.Proposal == nil {
441			if round != n.st.Round {
442				return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
443			}
444			return nil, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
445		}
446		if round != n.st.Proposal.Round {
447			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Proposal.Round)
448		}
449		if blockID != n.st.Proposal.BlockID {
450			return nil, reject(ReasonWrongBlock, "block id %s does not match proposal block id %s", blockID, n.st.Proposal.BlockID)
451		}
452	
453		for _, v := range n.st.Proposal.Votes {
454			if v == key {
455				return &VoteResult{Counted: false}, nil // 重复投票不增加票数
456			}
457		}
458	
459		st := n.st.clone()
460		st.Proposal.Votes = append(st.Proposal.Votes, key)
461		sort.Strings(st.Proposal.Votes)
462	
463		res := &VoteResult{Counted: true}
464		threshold := len(st.Validators) * 2 / 3
465		if len(st.Proposal.Votes) > threshold {
466			block := st.confirmProposal()
467			res.Confirmed = true
468			res.Block = &block
469		}
470		if err := n.save(st); err != nil {
471			return nil, err
472		}
473		n.st = st
474		return res, nil
475	}
476	
477	// confirmProposal 在内存状态上完整应用一次确认：
478	// 记录连续高度/前块标识/交易顺序，推进账户序号，移除已确认交易，进入下一轮，
479	// 并使新轮次中到期的池内交易失效。调用方随后通过一次原子保存落盘。
480	func (n *state) confirmProposal() Block {
481		p := n.Proposal
482		height := uint64(len(n.Blocks)) + 1
483		block := Block{
484			Height:     height,
485			Round:      p.Round,
486			ID:         p.BlockID,
487			PreviousID: n.LastBlock,
488			TxIDs:      append([]string(nil), p.TxIDs...),
489		}
490		if block.TxIDs == nil {
491			block.TxIDs = []string{}
492		}
493		for _, id := range block.TxIDs {
494			e := n.Entries[id]
495			sender := e.Tx.SenderHex()
496			// 打包保证序号连续且恰为下一条可确认序号。
497			n.Accounts[sender] = e.Tx.Sequence
498			delete(n.Pool[sender], e.Tx.Sequence)
499			if len(n.Pool[sender]) == 0 {
500				delete(n.Pool, sender)
501			}
502			e.Status = stConfirmed
503			e.ReplacedBy = ""
504			n.Confirmed[id] = confirmedRef{Height: height, Block: block.ID}
505		}
506		n.Blocks = append(n.Blocks, block)
507		n.LastBlock = block.ID
508		n.Proposal = nil
509		n.Round++
510		n.expire()
511		return block
512	}
513	
514	// expire 使池内到期轮次不大于当前轮次的交易失效。旧提议此时已不存在，
515	// 因此剩余池内交易均处于排队状态。
516	func (n *state) expire() {
517		for sender, seqs := range n.Pool {
518			for seq, id := range seqs {
519				e := n.Entries[id]
520				if e.Tx.Expiry <= n.Round {
521					e.Status = stExpired
522					delete(seqs, seq)
523				}
524			}
525			if len(seqs) == 0 {
526				delete(n.Pool, sender)
527			}
528		}
529	}
530	
531	// EndRound 主动结束当前未确认轮次：该轮不留下确认块，
532	// 原提议中的交易回到排队状态，随后进入下一轮并使到期交易失效。
533	// 旧轮次投票随提议一并清除，不能影响新提议。
534	func (n *Node) EndRound() (uint64, error) {
535		n.mu.Lock()
536		defer n.mu.Unlock()
537		st := n.st.clone()
538		if st.Proposal != nil {
539			for _, id := range st.Proposal.TxIDs {
540				if e, ok := st.Entries[id]; ok {
541					e.Status = stQueued
542				}
543			}
544			st.Proposal = nil
545		}
546		st.Round++
547		st.expire()
548		if err := n.save(st); err != nil {
549			return 0, err
550		}
551		n.st = st
552		return st.Round, nil
553	}
554	
555	// Height 返回已确认区块数（最新高度）。
556	func (n *Node) Height() uint64 {
557		n.mu.Lock()
558		defer n.mu.Unlock()
559		return uint64(len(n.st.Blocks))
560	}
561	
562	// BlockAt 按连续高度查询确认块，高度从 1 开始。
563	func (n *Node) BlockAt(height uint64) (Block, error) {
564		n.mu.Lock()
565		defer n.mu.Unlock()
566		if height == 0 || height > uint64(len(n.st.Blocks)) {
567			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
568		}
569		return n.st.Blocks[height-1], nil
570	}
571	
572	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
573	func (n *Node) LatestBlock() (Block, bool) {
574		n.mu.Lock()
575		defer n.mu.Unlock()
576		if len(n.st.Blocks) == 0 {
577			return Block{}, false
578		}
579		return n.st.Blocks[len(n.st.Blocks)-1], true
580	}
581	
582	// Tx 按交易标识查询其状态并关联区块或替代交易。
583	func (n *Node) Tx(id string) (*TxInfo, error) {
584		n.mu.Lock()
585		defer n.mu.Unlock()
586		if e, ok := n.st.Entries[id]; ok {
587			info := &TxInfo{
588				ID:         id,
589				Status:     TxStatus(e.Status),
590				Tx:         copyTx(e.Tx),
591				ReplacedBy: e.ReplacedBy,
592			}
593			if e.Status == stConfirmed {
594				if ref, ok := n.st.Confirmed[id]; ok {
595					info.BlockHeight = ref.Height
596					info.BlockID = ref.Block
597				}
598			}
599			return info, nil
600		}
601		return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
602	}
603	
604	// Account 按发送者公钥查询已确认序号与全部待处理交易。
605	// 因序号缺口等待时 Gap 给出最早缺少的序号；
606	// 已提议交易显示等待投票，其余池内交易显示等待打包。
607	func (n *Node) Account(sender []byte) *AccountInfo {
608		n.mu.Lock()
609		defer n.mu.Unlock()
610		key := fmt.Sprintf("%x", sender)
611		info := &AccountInfo{
612			Sender:            key,
613			ConfirmedSequence: n.st.Accounts[key],
614			Pending:           []*TxInfo{},
615		}
616		seqs := n.st.Pool[key]
617		if len(seqs) == 0 {
618			return info
619		}
620		seqList := make([]uint64, 0, len(seqs))
621		for seq := range seqs {
622			seqList = append(seqList, seq)
623		}
624		sort.Slice(seqList, func(i, j int) bool { return seqList[i] < seqList[j] })
625		expected := info.ConfirmedSequence + 1
626		var gap uint64
627		for _, seq := range seqList {
628			if gap == 0 {
629				if seq == expected {
630					expected++
631				} else if seq > expected {
632					gap = expected
633				}
634			}
635			id := seqs[seq]
636			e := n.st.Entries[id]
637			txInfo := &TxInfo{
638				ID:     id,
639				Status: TxStatus(e.Status),
640				Tx:     copyTx(e.Tx),
641			}
642			if e.Status == stProposed {
643				txInfo.Note = "waiting-vote"
644			} else {
645				txInfo.Note = "waiting-pack"
646			}
647			info.Pending = append(info.Pending, txInfo)
648		}
649		info.Gap = gap
650		return info
651	}
652	
653	func copyTx(tx *Transaction) *Transaction {
654		if tx == nil {
655			return nil
656		}
657		c := *tx
658		c.Sender = append([]byte(nil), tx.Sender...)
659		c.Content = append([]byte(nil), tx.Content...)
660		c.Signature = append([]byte(nil), tx.Signature...)
661		return &c
662	}
663

