393	func confirmByVotes(t *testing.T, n *Node, keys []testKey, blockID string) {
394		t.Helper()
395		round := n.CurrentRound()
396		// N=4 需 >2/3，即至少 3 票。
397		count := len(keys)*2/3 + 1
398		for i := 0; i < count; i++ {
399			res, err := n.Vote(keys[i].pub, round, blockID)
400			if err != nil {
401				t.Fatalf("vote %d: %v", i, err)
402			}
403			if i < count-1 && res.Confirmed {
404				t.Fatalf("confirmed too early at vote %d", i+1)
405			}
406			if i == count-1 {
407				if !res.Confirmed || res.Block == nil {
408					t.Fatalf("vote %d should confirm", i+1)
409				}
410			}
411		}
412	}
