	ids := append([]string(nil), c.TxIDs...)
	voters := make([][]byte, 0, len(c.Votes))
	for _, v := range c.Votes {
		voters = append(voters, hexToBytes(v))
	}
	return CandidateView{
		BlockID: c.BlockID,
		TxIDs:   ids,
		Voters:  voters,
		Status:  status,
		Local:   c.Local,
	}
}

// hexToBytes 将十六进制公钥串还原为原始字节。
func hexToBytes(h string) []byte {
	b := make([]byte, len(h)/2)
	for i := 0; i < len(b); i++ {
		var v byte
		for j := 0; j < 2; j++ {
			ch := h[i*2+j]
			var d byte
			switch {
			case ch >= '0' && ch <= '9':
				d = ch - '0'
			case ch >= 'a' && ch <= 'f':
				d = ch - 'a' + 10
			default:
				d = 0
			}
			v = v<<4 | d
		}
		b[i] = v
	}
	return b
}

