input.old_string:
// Vote 处理验证者投票。票数严格超过名单人数三分之二时立即确认。
// 名单外身份、错误轮次、错误区块标识返回带具体 Reason 的 *RejectError；
// 重复投同一票不增加票数但不报错。
func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	key := fmt.Sprintf("%x", validator)
	allowed := false
	for _, v := range n.st.Validators {
		if fmt.Sprintf("%x", v) == key {
			allowed = true
			break
		}
	}
	if !allowed {
		return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
	}
	// 轮次优先判定：旧轮次投票不能影响新提议，即使新轮次尚未产生提议。
	if n.st.Proposal == nil {
		if round != n.st.Round {
			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
		}
		return nil, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
	}
	if round != n.st.Proposal.Round {
		return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Proposal.Round)
	}
	if blockID != n.st.Proposal.BlockID {
		return nil, reject(ReasonWrongBlock, "block id %s does not match proposal block id %s", blockID, n.st.Proposal.BlockID)
	}

	for _, v := range n.st.Proposal.Votes {
		if v == key {
			return &VoteResult{Counted: false}, nil // 重复投票不增加票数
		}
	}

	st := n.st.clone()
	st.Proposal.Votes = append(st.Proposal.Votes, key)
	sort.Strings(st.Proposal.Votes)

	res := &VoteResult{Counted: true}
	threshold := len(st.Validators) * 2 / 3
	if len(st.Proposal.Votes) > threshold {
		block := st.confirmProposal()
		res.Confirmed = true
		res.Block = &block
	}
	if err := n.save(st); err != nil {
		return nil, err
	}
	n.st = st
	return res, nil
}

// confirmProposal 在内存状态上完整应用一次确认：
// 记录连续高度/前块标识/交易顺序，推进账户序号，移除已确认交易，进入下一轮，
// 并使新轮次中到期的池内交易失效。调用方随后通过一次原子保存落盘。
func (n *state) confirmProposal() Block {
	p := n.Proposal
	height := uint64(len(n.Blocks)) + 1
	block := Block{
		Height:     height,
		Round:      p.Round,
		ID:         p.BlockID,
		PreviousID: n.LastBlock,
		TxIDs:      append([]string(nil), p.TxIDs...),
	}
	if block.TxIDs == nil {
		block.TxIDs = []string{}
	}
	for _, id := range block.TxIDs {
		e := n.Entries[id]
		sender := e.Tx.SenderHex()
		// 打包保证序号连续且恰为下一条可确认序号。
		n.Accounts[sender] = e.Tx.Sequence
		delete(n.Pool[sender], e.Tx.Sequence)
		if len(n.Pool[sender]) == 0 {
			delete(n.Pool, sender)
		}
		e.Status = stConfirmed
		e.ReplacedBy = ""
		n.Confirmed[id] = confirmedRef{Height: height, Block: block.ID}
	}
	n.Blocks = append(n.Blocks, block)
	n.LastBlock = block.ID
	n.Proposal = nil
	n.Round++
	n.expire()
	return block
}

input.new_string:
// Vote 处理验证者投票。票数严格超过名单人数三分之二时立即确认该候选，
// 其他候选落选，随后进入下一轮。
// 名单外身份、错误轮次、未登记的区块标识返回带具体 Reason 的 *RejectError；
// 重复投同一候选不增加票数但不报错；改投其他候选明确拒绝，原票保留。
func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
	n.mu.Lock()
	defer n.mu.Unlock()

	key := fmt.Sprintf("%x", validator)
	allowed := false
	for _, v := range n.st.Validators {
		if fmt.Sprintf("%x", v) == key {
			allowed = true
			break
		}
	}
	if !allowed {
		return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
	}
	if round != n.st.Round {
		return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
	}
	var cand *candidateState
	for _, c := range n.st.Candidates {
		if c.BlockID == blockID {
			cand = c
			break
		}
	}
	if cand == nil {
		return nil, reject(ReasonWrongBlock, "block id %s is not a registered candidate in round %d", blockID, round)
	}

	for _, v := range cand.Votes {
		if v == key {
			return &VoteResult{Counted: false}, nil // 重复投同一候选不增加票数
		}
	}
	// 改投其他候选明确拒绝，原票保留。
	for _, c := range n.st.Candidates {
		if c.BlockID == blockID {
			continue
		}
		for _, v := range c.Votes {
			if v == key {
				return nil, reject(ReasonAlreadyVoted, "validator %s already voted for candidate %s in round %d", key, c.BlockID, round)
			}
		}
	}

	st := n.st.clone()
	var cloneCand *candidateState
	for _, c := range st.Candidates {
		if c.BlockID == blockID {
			cloneCand = c
			break
		}
	}
	cloneCand.Votes = append(cloneCand.Votes, key)
	sort.Strings(cloneCand.Votes)

	res := &VoteResult{Counted: true}
	threshold := len(st.Validators) * 2 / 3
	if len(cloneCand.Votes) > threshold {
		block := st.confirmCandidate(cloneCand)
		res.Confirmed = true
		res.Block = &block
	}
	if err := n.save(st); err != nil {
		return nil, err
	}
	n.st = st
	return res, nil
}

// confirmCandidate 在内存状态上完整应用一次候选确认：
// 胜出候选中的交易确认一次（推进账户序号、移出池中、标记已确认）；共享这些交易的
// 落选候选不再改变其状态；落选候选独有的交易回到排队状态。随后记录候选留档、
// 进入下一轮并使到期的池内交易失效。调用方随后通过一次原子保存落盘。
func (n *state) confirmCandidate(winner *candidateState) Block {
	height := uint64(len(n.Blocks)) + 1
	block := Block{
		Height:     height,
		Round:      n.Round,
		ID:         winner.BlockID,
		PreviousID: n.LastBlock,
		TxIDs:      append([]string(nil), winner.TxIDs...),
	}
	if block.TxIDs == nil {
		block.TxIDs = []string{}
	}
	won := make(map[string]bool, len(winner.TxIDs))
	for _, id := range block.TxIDs {
		won[id] = true
		e := n.Entries[id]
		sender := e.Tx.SenderHex()
