1	package consensus
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// Config 是节点初始化时固定的配置。
17	type Config struct {
18		// Seed 决定每轮提议者的种子，任意非空字节。
19		Seed []byte
20		// Validators 固定、非空、无重复的验证者公钥名单（Ed25519 32 字节公钥）。
21		Validators [][]byte
22		// MaxTxsPerBlock 单块交易上限，必须为正整数。
23		MaxTxsPerBlock uint64
24	}
25	
26	// entryStatus 与对外的 TxStatus 取值一致，额外区分内部存储。
27	type entryStatus string
28	
29	const (
30		stQueued    entryStatus = "queued"
31		stProposed  entryStatus = "proposed"
32		stConfirmed entryStatus = "confirmed"
33		stReplaced  entryStatus = "replaced"
34		stExpired   entryStatus = "expired"
35	)
36	
37	type poolEntry struct {
38		Tx         *Transaction `json:"tx"`
39		Status     entryStatus  `json:"status"`
40		ReplacedBy string       `json:"replaced_by,omitempty"`
41	}
42	
43	type confirmedRef struct {
44		Height uint64 `json:"height"`
45		Block  string `json:"block_id"`
46	}
47	
48	type proposalState struct {
49		Round   uint64   `json:"round"`
50		TxIDs   []string `json:"tx_ids"`
51		BlockID string   `json:"block_id"`
52		Votes   []string `json:"votes"` // 已投票验证者公钥的十六进制，按字典序保存
53	}
54	
55	// candidateState 是当前轮次的一个候选块。由 Propose 产生的本地候选 Local 为 true，
56	// 其余候选由 RegisterCandidate 登记。Votes 为已投票验证者公钥的十六进制，按字典序保存。
57	type candidateState struct {
58		BlockID string   `json:"block_id"`
59		TxIDs   []string `json:"tx_ids"`
60		Votes   []string `json:"votes"`
61		Local   bool     `json:"local,omitempty"`
62	}
63	
64	// candidateRecord 是已结束轮次中一个候选的留档。
65	type candidateRecord struct {
66		BlockID string   `json:"block_id"`
67		TxIDs   []string `json:"tx_ids"`
68		Votes   []string `json:"votes"`
69		Local   bool     `json:"local"`
70		Status  string   `json:"status"` // "won" 或 "lost"
71	}
72	
73	// roundRecord 是已结束轮次的候选留档，供按轮次查询。
74	type roundRecord struct {
75		Round      uint64             `json:"round"`
76		Candidates []*candidateRecord `json:"candidates"`
77		Ended      bool               `json:"ended"`                 // 主动结束，未确认任何区块
78		WonBlockID string             `json:"won_block_id,omitempty"` // 胜出候选区块标识
79	}
80	
81	// state 是持久化到磁盘的完整节点状态。
82	type state struct {
83		Version    int                          `json:"version"`
84		Seed       []byte                       `json:"seed"`
85		Validators [][]byte                     `json:"validators"`
86		MaxTxs     uint64                       `json:"max_txs_per_block"`
87		Round      uint64                       `json:"round"`
88		LastBlock  string                       `json:"last_block_id"`
89		Accounts   map[string]uint64            `json:"accounts"` // 发送者十六进制公钥 -> 已确认序号
90		Pool       map[string]map[uint64]string `json:"pool"`     // 发送者 -> 序号 -> 交易标识（含已提议交易）
91		Entries    map[string]*poolEntry        `json:"entries"`
92		Confirmed  map[string]confirmedRef      `json:"confirmed"`
93		Blocks     []Block                      `json:"blocks"`
94		Proposal   *proposalState               `json:"proposal,omitempty"` // 仅用于读取 v1 状态；新状态不再写入
95		Candidates []*candidateState            `json:"candidates,omitempty"`
96		History    []*roundRecord               `json:"history,omitempty"`
97	}
98	
99	const stateVersion = 2
100	const stateFileName = "state.json"
101	
102	// Node 是一个本地共识节点。一个进程内可串行调用其方法。
103	type Node struct {
104		dir string
105		mu  sync.Mutex
106		st  *state
107		// injectSaveErr 仅供同包测试使用：非 nil 时 save 直接失败，模拟写入错误。
108		injectSaveErr error
109	}
110	
111	func validateConfig(cfg Config) error {
112		if len(cfg.Seed) == 0 {
113			return errors.New("seed must be non-empty")
114		}
115		if len(cfg.Validators) == 0 {
116			return errors.New("validators must be non-empty")
117		}
118		if cfg.MaxTxsPerBlock == 0 {
119			return errors.New("max txs per block must be a positive integer")
120		}
121		seen := make(map[string]struct{}, len(cfg.Validators))
122		for i, v := range cfg.Validators {
123			if len(v) == 0 {
124				return fmt.Errorf("validator %d is empty", i)
125			}
126			key := fmt.Sprintf("%x", v)
127			if _, ok := seen[key]; ok {
128				return fmt.Errorf("duplicate validator %s", key)
129			}
130			seen[key] = struct{}{}
131		}
132		return nil
133	}
134	
135	// New 在 dir 中初始化一个新节点。目录不存在会创建；若已有状态文件则报错，
136	// 以免覆盖既有链历史，请改用 Open。
137	func New(dir string, cfg Config) (*Node, error) {
138		if err := validateConfig(cfg); err != nil {
139			return nil, err
140		}
141		if err := os.MkdirAll(dir, 0o755); err != nil {
142			return nil, err
143		}
144		path := filepath.Join(dir, stateFileName)
145		if _, err := os.Stat(path); err == nil {
146			return nil, fmt.Errorf("state file already exists at %s; use Open to resume", path)
147		}
148		validators := make([][]byte, len(cfg.Validators))
149		for i, v := range cfg.Validators {
150			validators[i] = append([]byte(nil), v...)
151		}
152		st := &state{
153			Version:    stateVersion,
154			Seed:       append([]byte(nil), cfg.Seed...),
155			Validators: validators,
156			MaxTxs:     cfg.MaxTxsPerBlock,
157			Round:      1, // 轮次从 1 开始
158			Accounts:   map[string]uint64{},
159			Pool:       map[string]map[uint64]string{},
160			Entries:    map[string]*poolEntry{},
161			Confirmed:  map[string]confirmedRef{},
162			Blocks:     []Block{},
163		}
164		n := &Node{dir: dir, st: st}
165		if err := n.save(st); err != nil {
166			return nil, err
167		}
168		return n, nil
169	}
170	
171	// Open 从 dir 恢复此前由 New 创建的节点，恢复轮次、交易池、未决候选、
172	// 每人已投的选择与确认历史。v1 状态目录仍可打开：未决提议与票数作为本地候选恢复，
173	// 但旧轮次没有保存候选详情，查询时明确显示无记录。
174	func Open(dir string) (*Node, error) {
175		path := filepath.Join(dir, stateFileName)
176		raw, err := os.ReadFile(path)
177		if err != nil {
178			return nil, err
179		}
180		st := &state{}
181		if err := json.Unmarshal(raw, st); err != nil {
182			return nil, fmt.Errorf("corrupt state file %s: %w", path, err)
183		}
184		if st.Version == 1 {
185			// 迁移：v1 的未决提议成为当前轮的本地候选，票数一并保留。
186			if st.Proposal != nil && len(st.Candidates) == 0 {
187				st.Candidates = []*candidateState{{
188					BlockID: st.Proposal.BlockID,
189					TxIDs:   append([]string(nil), st.Proposal.TxIDs...),
190					Votes:   append([]string(nil), st.Proposal.Votes...),
191					Local:   true,
192				}}
193			}
194			st.Proposal = nil
195			st.Version = 2
196		}
197		if st.Version != stateVersion {
198			return nil, fmt.Errorf("unsupported state version %d", st.Version)
199		}
200		if st.Round == 0 {
201			st.Round = 1
202		}
203		return &Node{dir: dir, st: st}, nil
204	}
205	
206	// ConfigSnapshot 返回节点的固定配置副本。
207	type ConfigSnapshot struct {
208		Seed           []byte
209		Validators     [][]byte
210		MaxTxsPerBlock uint64
211	}
212	
213	// Config 返回初始化时的配置副本。
214	func (n *Node) Config() ConfigSnapshot {
215		n.mu.Lock()
216		defer n.mu.Unlock()
217		vals := make([][]byte, len(n.st.Validators))
218		for i, v := range n.st.Validators {
219			vals[i] = append([]byte(nil), v...)
220		}
221		return ConfigSnapshot{
222			Seed:           append([]byte(nil), n.st.Seed...),
223			Validators:     vals,
224			MaxTxsPerBlock: n.st.MaxTxs,
225		}
226	}
227	
228	// CurrentRound 返回当前轮次，首轮为 1。
229	func (n *Node) CurrentRound() uint64 {
230		n.mu.Lock()
231		defer n.mu.Unlock()
232		return n.st.Round
233	}
234	
235	// proposerAt 是确定性的轮次提议者选择：
236	// 对 seed || round(大端 8 字节) 取 SHA-256，结果对名单人数取模。
237	// 种子、名单顺序与轮次相同时，提议者必然相同。
238	func proposerAt(seed []byte, validators [][]byte, round uint64) []byte {
239		var buf [8]byte
240		binary.BigEndian.PutUint64(buf[:], round)
241		h := sha256.New()
242		h.Write(seed)
243		h.Write(buf[:])
244		sum := h.Sum(nil)
245		idx := binary.BigEndian.Uint64(sum[:8]) % uint64(len(validators))
246		return validators[idx]
247	}
248	
249	// ProposerFor 返回指定轮次的提议者公钥。
250	func (n *Node) ProposerFor(round uint64) []byte {
251		n.mu.Lock()
252		defer n.mu.Unlock()
253		return append([]byte(nil), proposerAt(n.st.Seed, n.st.Validators, round)...)
254	}
255	
256	// CurrentProposer 返回当前轮次的提议者公钥。
257	func (n *Node) CurrentProposer() []byte {
258		return n.ProposerFor(n.CurrentRound())
259	}
260	
261	// SubmitResult 是交易提交结果。
262	type SubmitResult struct {
263		// TxID 被接受交易的标识。
264		TxID string
265		// ReplacedID 若本次提交替换了旧交易，为旧交易标识；否则为空。
266		ReplacedID string
267	}
268	
269	// Submit 校验并接收一笔交易进入交易池。
270	// 拒绝时返回 *RejectError，可通过其 Reason 取得具体原因。
271	func (n *Node) Submit(tx *Transaction) (*SubmitResult, error) {
272		if tx == nil {
273			return nil, errors.New("nil transaction")
274		}
275		n.mu.Lock()
276		defer n.mu.Unlock()
277	
278		cur := n.st
279		if tx.Sequence == 0 {
280			return nil, reject("sequence-must-be-positive", "sequence must be a positive integer")
281		}
282		if !tx.Verify() {
283			return nil, reject(ReasonBadSignature, "signature verification failed for sender %x", tx.Sender)
284		}
285		id := tx.ID()
286		// 同一标识的交易再次提交，一律视为重复（即使此前已确认、被替换或过期）。
287		if _, ok := cur.Entries[id]; ok {
288			return nil, reject(ReasonDuplicate, "transaction %s already exists", id)
289		}
290		if cur.Round >= tx.Expiry {
291			return nil, reject(ReasonExpired, "expiry round %d is not greater than current round %d", tx.Expiry, cur.Round)
292		}
293		sender := tx.SenderHex()
294		if confirmed := cur.Accounts[sender]; tx.Sequence <= confirmed {
295			return nil, reject(ReasonOldSequence, "sequence %d is not greater than confirmed sequence %d", tx.Sequence, confirmed)
296		}
297		seqs := cur.Pool[sender]
298		if seqs != nil {
299			if oldID, ok := seqs[tx.Sequence]; ok {
300				old := cur.Entries[oldID]
301				if old.Status == stProposed {
302					return nil, reject(ReasonProposalLocked, "sequence %d is already in the current proposal and cannot be replaced", tx.Sequence)
303				}
304				if tx.Fee <= old.Tx.Fee {
305					return nil, reject(ReasonLowFee, "new fee %d is not strictly higher than existing fee %d", tx.Fee, old.Tx.Fee)
306				}
307			}
308		}
309	
310		// 校验通过后在副本上修改，落盘成功才替换内存，失败时确认前状态保持不变。
311		st := cur.clone()
312		result := &SubmitResult{TxID: id}
313		if oldID, ok := st.Pool[sender][tx.Sequence]; ok {
314			old := st.Entries[oldID]
315			old.Status = stReplaced
316			old.ReplacedBy = id
317			result.ReplacedID = oldID
318		}
319	
320		txCopy := *tx
321		txCopy.Sender = append([]byte(nil), tx.Sender...)
322		txCopy.Content = append([]byte(nil), tx.Content...)
323		txCopy.Signature = append([]byte(nil), tx.Signature...)
324		st.Entries[id] = &poolEntry{Tx: &txCopy, Status: stQueued}
325		if st.Pool[sender] == nil {
326			st.Pool[sender] = map[uint64]string{}
327		}
328		st.Pool[sender][tx.Sequence] = id
329	
330		if err := n.save(st); err != nil {
331			return nil, err
332		}
333		n.st = st
334		return result, nil
335	}
336	
337	// 额外拒绝原因。
338	const (
339		// ReasonProposalLocked 同发送者同序号交易已在当前提议中，禁止替换。
340		ReasonProposalLocked = "tx-in-proposal"
341		// ReasonUnknownTx 查询的交易标识不存在。
342		ReasonUnknownTx = "unknown-transaction"
343		// ReasonUnknownBlock 查询的区块高度不存在。
344		ReasonUnknownBlock = "unknown-block"
345	)
346	
347	// ProposalView 是当前轮次提议的只读视图。
348	type ProposalView struct {
349		Round   uint64
350		BlockID string
351		TxIDs   []string
352		// Empty 表示本轮是否为空块提议（无交易）。
353		Empty bool
354	}
355	
356	// localCandidate 返回当前轮由 Propose 产生的本地候选；不存在时返回 nil。
357	func (n *Node) localCandidate() *candidateState {
358		for _, c := range n.st.Candidates {
359			if c.Local {
360				return c
361			}
362		}
363		return nil
364	}
365	
366	// Proposal 返回当前轮次的本地提议；尚未提议时第二个返回值为 false。
367	// 重复调用返回同一内容；登记其他候选不会改变本地提议。
368	func (n *Node) Proposal() (ProposalView, bool) {
369		n.mu.Lock()
370		defer n.mu.Unlock()
371		c := n.localCandidate()
372		if c == nil {
373			return ProposalView{}, false
374		}
375		return proposalView(c, n.st.Round), true
376	}
377	
378	// Propose 返回当前轮次唯一的本地提议；重复请求返回同一提议。
379	// 提议生成后即冻结：此后新提交的交易不改变该提议，提议中的交易禁止替换。
380	// 本地提议是当前轮的候选之一，可与 RegisterCandidate 登记的其他候选一起参与投票。
381	func (n *Node) Propose() (ProposalView, error) {
382		n.mu.Lock()
383		defer n.mu.Unlock()
384		if c := n.localCandidate(); c != nil {
385			return proposalView(c, n.st.Round), nil
386		}
387	
388		st := n.st.clone()
389		txIDs := st.selectTransactions()
390		height := uint64(len(st.Blocks)) + 1
391		blockID := BlockID(st.Round, height, st.LastBlock, txIDs)
392		cand := &candidateState{
393			BlockID: blockID,
394			TxIDs:   txIDs,
395			Votes:   []string{},
396			Local:   true,
397		}
398		st.Candidates = append(st.Candidates, cand)
399		for _, id := range txIDs {
400			st.Entries[id].Status = stProposed
401		}
402		if err := n.save(st); err != nil {
403			return ProposalView{}, err
404		}
405		n.st = st
406		return proposalView(cand, n.st.Round), nil
407	}
408	
409	func proposalView(c *candidateState, round uint64) ProposalView {
410		ids := append([]string(nil), c.TxIDs...)
411		return ProposalView{Round: round, BlockID: c.BlockID, TxIDs: ids, Empty: len(ids) == 0}
412	}
413	
414	// candidateView 构造候选的只读视图，深拷贝交易标识与投票者公钥，
415	// 调用者修改返回结果不会影响节点状态。
416	func candidateView(c *candidateState, status CandidateStatus) CandidateView {
417		ids := append([]string(nil), c.TxIDs...)
418		voters := make([][]byte, 0, len(c.Votes))
419		for _, v := range c.Votes {
420			b, _ := hex.DecodeString(v)
421			voters = append(voters, b)
422		}
423		return CandidateView{
424			BlockID: c.BlockID,
425			TxIDs:   ids,
426			Voters:  voters,
427			Status:  status,
428			Local:   c.Local,
429		}
430	}
431	
432	// RegisterCandidate 在当前轮已有本地提议且尚未确认时，按调用者给定的交易顺序
433	// 登记一个候选块，与本地提议一起参与投票。候选使用当前轮次与下一高度，接在最新
434	// 确认块之后，不改变已确认历史。
435	//
436	// 候选中的交易必须是当前池内排队或已提议的交易；数量不得超过单块上限，允许空块；
437	// 列表不得重复交易；同一账户的序号必须从该账户已确认序号加一开始连续递增（账户
438	// 之间的顺序由调用者决定）。
439	//
440	// 未产生本地提议、指定非当前轮次、引用未知或已退出池的交易、超过上限或序号不连续
441	// 时登记失败，返回带具体 Reason 的 *RejectError，节点状态不变。相同列表重复登记
442	// 返回同一候选并保留已有票数。
443	func (n *Node) RegisterCandidate(round uint64, txIDs []string) (CandidateView, error) {
444		n.mu.Lock()
445		defer n.mu.Unlock()
446	
447		if n.localCandidate() == nil {
448			return CandidateView{}, reject(ReasonNoProposal, "round %d has no proposal", n.st.Round)
449		}
450		if round != n.st.Round {
451			return CandidateView{}, reject(ReasonWrongRound, "candidate round %d does not match current round %d", round, n.st.Round)
452		}
453	
454		// 列表不得重复交易。
455		seen := make(map[string]bool, len(txIDs))
456		for _, id := range txIDs {
457			if seen[id] {
458				return CandidateView{}, reject(ReasonDuplicateTxInCandidate, "transaction %s appears more than once in candidate", id)
459			}
460			seen[id] = true
461		}
462		// 数量不得超过单块上限。
463		if uint64(len(txIDs)) > n.st.MaxTxs {
464			return CandidateView{}, reject(ReasonTooManyTxs, "candidate has %d transactions, exceeds max %d", len(txIDs), n.st.MaxTxs)
465		}
466		// 交易必须存在且当前在池中（排队或已提议）。
467		for _, id := range txIDs {
468			e, ok := n.st.Entries[id]
469			if !ok {
470				return CandidateView{}, reject(ReasonUnknownTx, "transaction %s not found", id)
471			}
472			if e.Status != stQueued && e.Status != stProposed {
473				return CandidateView{}, reject(ReasonTxNotInPool, "transaction %s is not in pool (status %s)", id, e.Status)
474			}
475		}
476		// 同一账户的序号必须从已确认序号加一开始连续递增。
477		senderSeqs := make(map[string][]uint64)
478		for _, id := range txIDs {
479			sender := n.st.Entries[id].Tx.SenderHex()
480			senderSeqs[sender] = append(senderSeqs[sender], n.st.Entries[id].Tx.Sequence)
481		}
482		for sender, seqs := range senderSeqs {
483			expected := n.st.Accounts[sender] + 1
484			for _, seq := range seqs {
485				if seq != expected {
486					return CandidateView{}, reject(ReasonSequenceGap, "sender %s sequence %d is not consecutive after confirmed %d", sender, seq, expected-1)
487				}
488				expected++
489			}
490		}
491	
492		height := uint64(len(n.st.Blocks)) + 1
493		blockID := BlockID(n.st.Round, height, n.st.LastBlock, txIDs)
494		// 相同列表（同一区块标识）重复登记返回同一候选，保留已有票数。
495		for _, c := range n.st.Candidates {
496			if c.BlockID == blockID {
497				return candidateView(c, CandidatePending), nil
498			}
499		}
500	
501		st := n.st.clone()
502		cand := &candidateState{
503			BlockID: blockID,
504			TxIDs:   append([]string(nil), txIDs...),
505			Votes:   []string{},
506		}
507		st.Candidates = append(st.Candidates, cand)
508		for _, id := range txIDs {
509			st.Entries[id].Status = stProposed
510		}
511		if err := n.save(st); err != nil {
512			return CandidateView{}, err
513		}
514		n.st = st
515		return candidateView(cand, CandidatePending), nil
516	}
517	
518	// selectTransactions 执行确定性打包：
519	// 每轮从各账户“下一条可确认”的交易中选费用最高者，费用相同按交易标识字典序；
520	// 选入某账户后才继续考虑其后续序号，直到达到上限或没有可选交易。
521	func (n *state) selectTransactions() []string {
522		var picked []string
523		// 每个账户在本次打包中下一个可考虑的序号。
524		next := map[string]uint64{}
525		for sender := range n.Pool {
526			next[sender] = n.Accounts[sender] + 1
527		}
528		for uint64(len(picked)) < n.MaxTxs {
529			var bestID string
530			var bestFee uint64
531			var bestSet bool
532			// 遍历发送者名单需确定序：按发送者十六进制定序，保证选择只取决于费用与标识。
533			senders := make([]string, 0, len(n.Pool))
534			for s := range n.Pool {
535				senders = append(senders, s)
536			}
537			sort.Strings(senders)
538			for _, sender := range senders {
539				id, ok := n.Pool[sender][next[sender]]
540				if !ok {
541					continue
542				}
543				e := n.Entries[id]
544				if e.Status != stQueued {
545					continue
546				}
547				if !bestSet || e.Tx.Fee > bestFee || (e.Tx.Fee == bestFee && id < bestID) {
548					bestID = id
549					bestFee = e.Tx.Fee
550					bestSet = true
551				}
552			}
553			if !bestSet {
554				break
555			}
556			picked = append(picked, bestID)
557			next[n.Entries[bestID].Tx.SenderHex()]++
558		}
559		if picked == nil {
560			picked = []string{}
561		}
562		return picked
563	}
564	
565	// VoteResult 是投票处理结果。
566	type VoteResult struct {
567		// Counted 本次投票是否新计入票数（重复投同一票为 false）。
568		Counted bool
569		// Confirmed 本次投票是否令区块立即确认。
570		Confirmed bool
571		// Block 确认时为新区块；否则为 nil。
572		Block *Block
573	}
574	
575	// Vote 处理验证者投票。票数严格超过名单人数三分之二时立即确认该候选，
576	// 其他候选落选，随后进入下一轮。
577	// 名单外身份、错误轮次、未登记的区块标识返回带具体 Reason 的 *RejectError；
578	// 重复投同一候选不增加票数但不报错；改投其他候选明确拒绝，原票保留。
579	func (n *Node) Vote(validator []byte, round uint64, blockID string) (*VoteResult, error) {
580		n.mu.Lock()
581		defer n.mu.Unlock()
582	
583		key := fmt.Sprintf("%x", validator)
584		allowed := false
585		for _, v := range n.st.Validators {
586			if fmt.Sprintf("%x", v) == key {
587				allowed = true
588				break
589			}
590		}
591		if !allowed {
592			return nil, reject(ReasonNotValidator, "validator %s is not in the validator set", key)
593		}
594		if round != n.st.Round {
595			return nil, reject(ReasonWrongRound, "vote round %d does not match current round %d", round, n.st.Round)
596		}
597		var cand *candidateState
598		for _, c := range n.st.Candidates {
599			if c.BlockID == blockID {
600				cand = c
601				break
602			}
603		}
604		if cand == nil {
605			return nil, reject(ReasonWrongBlock, "block id %s is not a registered candidate in round %d", blockID, round)
606		}
607	
608		for _, v := range cand.Votes {
609			if v == key {
610				return &VoteResult{Counted: false}, nil // 重复投同一候选不增加票数
611			}
612		}
613		// 改投其他候选明确拒绝，原票保留。
614		for _, c := range n.st.Candidates {
615			if c.BlockID == blockID {
616				continue
617			}
618			for _, v := range c.Votes {
619				if v == key {
620					return nil, reject(ReasonAlreadyVoted, "validator %s already voted for candidate %s in round %d", key, c.BlockID, round)
621				}
622			}
623		}
624	
625		st := n.st.clone()
626		var cloneCand *candidateState
627		for _, c := range st.Candidates {
628			if c.BlockID == blockID {
629				cloneCand = c
630				break
631			}
632		}
633		cloneCand.Votes = append(cloneCand.Votes, key)
634		sort.Strings(cloneCand.Votes)
635	
636		res := &VoteResult{Counted: true}
637		threshold := len(st.Validators) * 2 / 3
638		if len(cloneCand.Votes) > threshold {
639			block := st.confirmCandidate(cloneCand)
640			res.Confirmed = true
641			res.Block = &block
642		}
643		if err := n.save(st); err != nil {
644			return nil, err
645		}
646		n.st = st
647		return res, nil
648	}
649	
650	// confirmCandidate 在内存状态上完整应用一次候选确认：
651	// 胜出候选中的交易确认一次（推进账户序号、移出池中、标记已确认）；共享这些交易的
652	// 落选候选不再改变其状态；落选候选独有的交易回到排队状态。随后记录候选留档、
653	// 进入下一轮并使到期的池内交易失效。调用方随后通过一次原子保存落盘。
654	func (n *state) confirmCandidate(winner *candidateState) Block {
655		height := uint64(len(n.Blocks)) + 1
656		block := Block{
657			Height:     height,
658			Round:      n.Round,
659			ID:         winner.BlockID,
660			PreviousID: n.LastBlock,
661			TxIDs:      append([]string(nil), winner.TxIDs...),
662		}
663		if block.TxIDs == nil {
664			block.TxIDs = []string{}
665		}
666		won := make(map[string]bool, len(winner.TxIDs))
667		for _, id := range block.TxIDs {
668			won[id] = true
669			e := n.Entries[id]
670			sender := e.Tx.SenderHex()
671			// 候选列表保证序号连续且从已确认序号加一开始。
672			n.Accounts[sender] = e.Tx.Sequence
673			delete(n.Pool[sender], e.Tx.Sequence)
674			if len(n.Pool[sender]) == 0 {
675				delete(n.Pool, sender)
676			}
677			e.Status = stConfirmed
678			e.ReplacedBy = ""
679			n.Confirmed[id] = confirmedRef{Height: height, Block: winner.BlockID}
680		}
681		// 落选候选独有的交易回到排队状态；共享胜出交易的保持已确认不变。
682		for _, c := range n.Candidates {
683			if c.BlockID == winner.BlockID {
684				continue
685			}
686			for _, id := range c.TxIDs {
687				if won[id] {
688					continue
689				}
690				e := n.Entries[id]
691				if e.Status == stProposed {
692					e.Status = stQueued
693				}
694			}
695		}
696		n.appendHistory(winner.BlockID, false)
697		n.Blocks = append(n.Blocks, block)
698		n.LastBlock = winner.BlockID
699		n.Candidates = nil
700		n.Round++
701		n.expire()
702		return block
703	}
704	
705	// appendHistory 把当前轮的候选留档追加到历史。胜出候选状态为 won，其余为 lost；
706	// 主动结束的轮次所有候选均为 lost 且 Ended 为 true。
707	func (n *state) appendHistory(wonBlockID string, ended bool) {
708		rec := &roundRecord{
709			Round:      n.Round,
710			Ended:      ended,
711			WonBlockID: wonBlockID,
712			Candidates: make([]*candidateRecord, 0, len(n.Candidates)),
713		}
714		for _, c := range n.Candidates {
715			status := "lost"
716			if c.BlockID == wonBlockID {
717				status = "won"
718			}
719			rec.Candidates = append(rec.Candidates, &candidateRecord{
720				BlockID: c.BlockID,
721				TxIDs:   append([]string(nil), c.TxIDs...),
722				Votes:   append([]string(nil), c.Votes...),
723				Local:   c.Local,
724				Status:  status,
725			})
726		}
727		n.History = append(n.History, rec)
728	}
729	
730	// expire 使池内到期轮次不大于当前轮次的交易失效。旧提议此时已不存在，
731	// 因此剩余池内交易均处于排队状态。
732	func (n *state) expire() {
733		for sender, seqs := range n.Pool {
734			for seq, id := range seqs {
735				e := n.Entries[id]
736				if e.Tx.Expiry <= n.Round {
737					e.Status = stExpired
738					delete(seqs, seq)
739				}
740			}
741			if len(seqs) == 0 {
742				delete(n.Pool, sender)
743			}
744		}
745	}
746	
747	// EndRound 主动结束当前未确认轮次：所有候选落选且不留下确认块，
748	// 候选中的交易回到排队状态（进入新轮次时到期的显示过期），随后进入下一轮。
749	// 该轮作为“未确认结束”留档，旧投票不影响新提议。
750	func (n *Node) EndRound() (uint64, error) {
751		n.mu.Lock()
752		defer n.mu.Unlock()
753		st := n.st.clone()
754		for _, c := range st.Candidates {
755			for _, id := range c.TxIDs {
756				if e, ok := st.Entries[id]; ok && e.Status == stProposed {
757					e.Status = stQueued
758				}
759			}
760		}
761		st.appendHistory("", true)
762		st.Candidates = nil
763		st.Round++
764		st.expire()
765		if err := n.save(st); err != nil {
766			return 0, err
767		}
768		n.st = st
769		return st.Round, nil
770	}
771	
772	// RoundCandidates 按轮次查询候选：列出每个候选的交易顺序、投票者及未决/胜出/
773	// 落选结果，并列出本轮尚未投票的验证者；主动结束的轮次明确显示未确认结束。
774	// 候选按区块标识排序，投票者与未投票验证者按公钥排序。返回结果为深拷贝，
775	// 调用者修改不影响节点状态。
776	func (n *Node) RoundCandidates(round uint64) (RoundView, error) {
777		n.mu.Lock()
778		defer n.mu.Unlock()
779	
780		view := RoundView{Round: round, Candidates: []*CandidateView{}}
781		var src []*candidateState
782		if round == n.st.Round {
783			// 当前轮：候选均未决。
784			for _, c := range n.st.Candidates {
785				src = append(src, c)
786			}
787		} else if round < n.st.Round {
788			// 历史轮：从留档读取。
789			var rec *roundRecord
790			for _, h := range n.st.History {
791				if h.Round == round {
792					rec = h
793					break
794				}
795			}
796			if rec == nil {
797				return RoundView{}, reject(ReasonUnknownRound, "round %d has no candidate records", round)
798			}
799			view.Ended = rec.Ended
800			view.Confirmed = rec.WonBlockID != ""
801			view.WonBlockID = rec.WonBlockID
802			for _, cr := range rec.Candidates {
803				status := CandidateLost
804				if cr.Status == "won" {
805					status = CandidateWon
806				}
807				cv := candidateView(&candidateState{
808					BlockID: cr.BlockID,
809					TxIDs:   cr.TxIDs,
810					Votes:   cr.Votes,
811					Local:   cr.Local,
812				}, status)
813				view.Candidates = append(view.Candidates, &cv)
814			}
815		} else {
816			return RoundView{}, reject(ReasonUnknownRound, "round %d has not been reached (current %d)", round, n.st.Round)
817		}
818	
819		if round == n.st.Round {
820			for _, c := range src {
821				cv := candidateView(c, CandidatePending)
822				view.Candidates = append(view.Candidates, &cv)
823			}
824		}
825	
826		// 候选按区块标识排序。
827		sort.Slice(view.Candidates, func(i, j int) bool {
828			return view.Candidates[i].BlockID < view.Candidates[j].BlockID
829		})
830	
831		// 尚未投票的验证者：名单中未在任何候选投票者里出现的人，按公钥排序。
832		voted := make(map[string]bool)
833		for _, cv := range view.Candidates {
834			for _, v := range cv.Voters {
835				voted[fmt.Sprintf("%x", v)] = true
836			}
837		}
838		for _, v := range n.st.Validators {
839			if !voted[fmt.Sprintf("%x", v)] {
840				view.NotVoted = append(view.NotVoted, append([]byte(nil), v...))
841			}
842		}
843		sort.Slice(view.NotVoted, func(i, j int) bool {
844			return string(view.NotVoted[i]) < string(view.NotVoted[j])
845		})
846		return view, nil
847	}
848	
849	// Height 返回已确认区块数（最新高度）。
850	func (n *Node) Height() uint64 {
851		n.mu.Lock()
852		defer n.mu.Unlock()
853		return uint64(len(n.st.Blocks))
854	}
855	
856	// BlockAt 按连续高度查询确认块，高度从 1 开始。
857	func (n *Node) BlockAt(height uint64) (Block, error) {
858		n.mu.Lock()
859		defer n.mu.Unlock()
860		if height == 0 || height > uint64(len(n.st.Blocks)) {
861			return Block{}, reject(ReasonUnknownBlock, "block at height %d does not exist", height)
862		}
863		return n.st.Blocks[height-1], nil
864	}
865	
866	// LatestBlock 返回最新确认块；尚无确认块时第二返回值为 false。
867	func (n *Node) LatestBlock() (Block, bool) {
868		n.mu.Lock()
869		defer n.mu.Unlock()
870		if len(n.st.Blocks) == 0 {
871			return Block{}, false
872		}
873		return n.st.Blocks[len(n.st.Blocks)-1], true
874	}
875	
876	// Tx 按交易标识查询其状态并关联区块或替代交易。
877	func (n *Node) Tx(id string) (*TxInfo, error) {
878		n.mu.Lock()
879		defer n.mu.Unlock()
880		if e, ok := n.st.Entries[id]; ok {
881			info := &TxInfo{
882				ID:         id,
883				Status:     TxStatus(e.Status),
884				Tx:         copyTx(e.Tx),
885				ReplacedBy: e.ReplacedBy,
886			}
887			if e.Status == stConfirmed {
888				if ref, ok := n.st.Confirmed[id]; ok {
889					info.BlockHeight = ref.Height
890					info.BlockID = ref.Block
891				}
892			}
893			return info, nil
894		}
895		return nil, reject(ReasonUnknownTx, "transaction %s not found", id)
896	}
897	
898	// Account 按发送者公钥查询已确认序号与全部待处理交易。
899	// 因序号缺口等待时 Gap 给出最早缺少的序号；
900	// 已提议交易显示等待投票，其余池内交易显示等待打包。
901	func (n *Node) Account(sender []byte) *AccountInfo {
902		n.mu.Lock()
903		defer n.mu.Unlock()
904		key := fmt.Sprintf("%x", sender)
905		info := &AccountInfo{
906			Sender:            key,
907			ConfirmedSequence: n.st.Accounts[key],
908			Pending:           []*TxInfo{},
909		}
910		seqs := n.st.Pool[key]
911		if len(seqs) == 0 {
912			return info
913		}
914		seqList := make([]uint64, 0, len(seqs))
915		for seq := range seqs {
916			seqList = append(seqList, seq)
917		}
918		sort.Slice(seqList, func(i, j int) bool { return seqList[i] < seqList[j] })
919		expected := info.ConfirmedSequence + 1
920		var gap uint64
921		for _, seq := range seqList {
922			if gap == 0 {
923				if seq == expected {
924					expected++
925				} else if seq > expected {
926					gap = expected
927				}
928			}
929			id := seqs[seq]
930			e := n.st.Entries[id]
931			txInfo := &TxInfo{
932				ID:     id,
933				Status: TxStatus(e.Status),
934				Tx:     copyTx(e.Tx),
935			}
936			if e.Status == stProposed {
937				txInfo.Note = "waiting-vote"
938			} else {
939				txInfo.Note = "waiting-pack"
940			}
941			info.Pending = append(info.Pending, txInfo)
942		}
943		info.Gap = gap
944		return info
945	}
946	
947	func copyTx(tx *Transaction) *Transaction {
948		if tx == nil {
949			return nil
950		}
951		c := *tx
952		c.Sender = append([]byte(nil), tx.Sender...)
953		c.Content = append([]byte(nil), tx.Content...)
954		c.Signature = append([]byte(nil), tx.Signature...)
955		return &c
956	}
957

